 \hbox to 4cm{#2\hss}%
}
\leavevmode
\hbox to 3.4cm{$\hmat{2 3 2 1 0 0; 1 0 3 0 1 0; 2 2 3 0 0 1}$\hss}%
\rowop{R_1 \longleftrightarrow R_2}{%
$\hmat{\r1 0 3 0 1 0; 2 3 2 1 0 0; 2 2 3 0 0 1}$} \\[2mm]
\leavevmode\hbox to 3.4cm{}\rowop{%
